create table attrs_types
(
  id        int primary key,
  name      varchar(50)  not null unique,
  element   varchar(30)  not null,
  maxlength int null,
  size      int null
);



create table attrs_item_types
(
  id   int primary key,
  name varchar(50) not null unique
);



create table attrs_zones
(
  id           int primary key,
  name         varchar(50) not null unique,
  item_type_id int not null,
  constraint attrs_zones_fk foreign key (item_type_id) references attrs_item_types (id)
);

create index item_type_id on attrs_zones (item_type_id);



create table attrs_units
(
  id   int primary key,
  name varchar(50) not null unique,
  abbr varchar(30) not null unique
);



create table attrs_attributes
(
  id          int primary key,
  name        varchar(50) not null,
  type_id     int         null,
  parent_id   int         null,
  unit_id     int         null,
  description text        null,
  precision   int         null,
  position    int         not null,
  multiple    bool default false not null,
  constraint attrs_attributes_unique_name unique (name, parent_id),
  constraint attrs_attributes_unique_position unique (position, parent_id),
  constraint attrs_attributes_fk foreign key (type_id) references attrs_types (id),
  constraint attrs_attributes_fk1 foreign key (parent_id) references attrs_attributes (id),
  constraint attrs_attributes_fk2 foreign key (unit_id) references attrs_units (id)
);

create index parent_id on attrs_attributes (parent_id);
create index type on attrs_attributes (type_id);
create index unit_id on attrs_attributes (unit_id);

ALTER TABLE attrs_attributes DISABLE TRIGGER ALL;
ALTER TABLE attrs_attributes ENABLE TRIGGER ALL;


create table attrs_zone_attributes
(
  zone_id      int not null,
  attribute_id int not null,
  position     int not null,
  primary key (attribute_id, zone_id),
  constraint attrs_zone_attributes_unique_position unique (zone_id, position),
  constraint attrs_zone_attributes_fk foreign key (zone_id) references attrs_zones (id),
  constraint attrs_zone_attributes_fk1 foreign key (attribute_id) references attrs_attributes (id)
);

